 "content": "def transform(grid):
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # A full solid stripe acts as the template; a matching partial stripe is
    # extended with the designated color 1 over its missing tail.
    full = [row for row in grid if all(v == row[0] for v in row) and row[0] != bg]
    if full:
        color = full[0][0]
        for r, row in enumerate(grid):
            if row[0] == color:
                k = 0
                while k < len(row) and row[k] == color:
                    k += 1
                if 0 < k < len(row) and all(v == bg for v in row[k:]):
                    out[r][k:] = [1] * (len(row)-k)
    return out
